package com.example.sumayerestaurant.ui.finance;
import android.os.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.sumayerestaurant.data.api.RetrofitClient;import com.example.sumayerestaurant.data.local.TokenManager;import com.example.sumayerestaurant.data.model.*;import java.time.LocalDate;import retrofit2.*;
public class ReportActivity extends AppCompatActivity{private Long branch;private EditText date;private TextView result;@Override public void onCreate(Bundle b){super.onCreate(b);User u=new TokenManager(this).getUser();branch=(u==null||u.getBranchId()==null)?1L:u.getBranchId();setTitle("Ripoti ya Faida/Hasara");LinearLayout root=new LinearLayout(this);root.setPadding(28,28,28,28);root.setOrientation(LinearLayout.VERTICAL);date=new EditText(this);date.setHint("Tarehe (YYYY-MM-DD)");date.setText(LocalDate.now().toString());root.addView(date);Button show=new Button(this);show.setText("Onyesha ripoti");root.addView(show);result=new TextView(this);result.setTextSize(20);root.addView(result);setContentView(root);show.setOnClickListener(v->load());load();}private void load(){if(branch==null){result.setText("Tawi halijapatikana.");return;}RetrofitClient.getApiService(this).profitLoss(branch,date.getText().toString(),date.getText().toString()).enqueue(new Callback<ProfitLoss>(){public void onResponse(Call<ProfitLoss>c,Response<ProfitLoss>r){if(!r.isSuccessful()||r.body()==null){result.setText("Imeshindikana kupakia ripoti.");return;}ProfitLoss p=r.body();result.setText("MAPATO\nTZS "+p.getSales()+"\n\nGHARAMA\nTZS "+p.getOperatingExpenses()+"\n\nFAIDA INAYOKADIRIWA\nTZS "+p.getEstimatedProfit()+"\n\n"+p.getLabel());}public void onFailure(Call<ProfitLoss>c,Throwable t){result.setText("Hakuna mtandao. Tafadhali jaribu tena.");}});}}
